pub fn ota_start(octet_stream: bool, content_length: usize, transfer_encoding: bool) -> OtaStart {
    if !octet_stream {
        OtaStart::WrongContentType
    } else if content_length == 0 {
        if transfer_encoding { OtaStart::Chunked } else { OtaStart::Empty }
    } else {
        OtaStart::Proceed
    }
}

