pub fn encode_message(msg: &[u8], out: &mut [u8]) -> Option<usize> {
    let mut i: usize = 0;
    let mut n: usize = 0;
    while i < msg.len() {
        let b = msg[i];
        if b == LT || b == GT {
            return None;
        }
        let code = if b == UTF8_C3 && i + 1 < msg.len() { umlaut_code(msg[i + 1]) } else { 0 };
        if code != 0 {
            if out.len() < 5 || n > out.len() - 5 {
                return None;
            }
            out[n] = LT;
            out[n + 1] = CAP_U;
            out[n + 2] = hex_upper(code >> 4);
            out[n + 3] = hex_upper(code & 15);
            out[n + 4] = GT;
            n += 5;
            i += 2;
        } else {
            if n >= out.len() {
                return None;
            }
            out[n] = b;
            n += 1;
            i += 1;
        }
    }
    Some(n)
}

